import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"15、【谦】 艮下坤上","description":"周易口诀义 - 15、【谦】 艮下坤上","frontmatter":{"title":"15、【谦】 艮下坤上","description":"周易口诀义 - 15、【谦】 艮下坤上"},"headers":[],"relativePath":"zh/classics/koujueyi/017.md","filePath":"zh/classics/koujueyi/017.md"}'),r={name:"zh/classics/koujueyi/017.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_15、【谦】-艮下坤上" tabindex="-1">15、【谦】 艮下坤上 <a class="header-anchor" href="#_15、【谦】-艮下坤上" aria-label="Permalink to “15、【谦】 艮下坤上”">​</a></h1><p>彖曰：「谦亨」。天道下济而光明，地道卑而上行。天道亏盈而益谦，地道变盈而流谦，鬼神害盈而福谦，人道恶盈而好谦。谦尊而光，卑而不可逾，君子之终也。</p><p>象曰：地中有山，谦。君子以裒多益寡，称物平施。</p><p>初六：谦谦君子，用涉大川，吉。</p><p>象曰：「谦谦君子」，卑以自牧也。</p><p>六二：鸣谦，贞吉。</p><p>象曰：「鸣谦贞吉」，中心得也。</p><p>九三：劳谦，君子有终，吉。</p><p>象曰：「劳谦君子」，万民服也。</p><p>六四：无不利，㧑谦。</p><p>象曰：「无不利，㧑谦」，不违则也。</p><p>六五，不富以其邻，利用侵伐，无不利。</p><p>象曰：「利用侵伐」，征不服也。</p><p>上六，鸣谦，利用行师，征邑国。</p><p>象曰：「鸣谦」，志未得也。可用行师，征邑国也。</p><p>解读</p><p>谦亨者，谦是屈己先人，以自卑巽为用，如是何往而不亨也！「君子有终」者，小人行谦，多不能久，惟有君子尽能保终也。象曰「地中有山，谦」者，九家易义曰：山至高，地至卑，以高下卑，故云谦也。所以言地中者，以明多之与少，俱行其谦也。「君子以裒多益寡，称物平施」者，裒，聚也；寡，少也；谓人资财此多者行谦，即物益裒聚，故曰「裒多」也；比寡少行谦，即物渐增益，故曰「益寡」也；称量事物，随其多少，均平而施给，故曰「称物平施」也。</p><p>「初六，谦谦君子，用涉大川，吉」者，处谦更在下，则是卑退之甚也，故曰「谦谦」也；君子以谦自牧，守谦不失，用济大难，物无见害，故曰「用涉大川，吉」。牧，养也。</p><p>「六二鸣谦，贞吉」者，鸣者，声名闻之谓也。处谦之时，位居中正，即谦之声闻于外境，是正而获吉，故曰「鸣谦，贞吉」。</p><p>「九三：劳谦，君子有终，吉」者，九三以刚阳之质，为一卦之主，上即承奉于君，下又抚绥万人，劳勤于谦，以君子处之，能保其终而获吉。</p><p>「六四：无不利，㧑谦」者，六四上近至尊，下近权臣，处是时，不可违于谦巽，故三之于五，有事指㧑，无不从顺，不敢违于法则，故曰「无不利，㧑谦」也。</p><p>六五：不富以其邻，利用侵伐，无不利者，六五为谦之君，教化大行，下既行「谦」，人自富贵，故不假以财物，赒赡于邻，故曰「不富以其邻」。身既谦卑，不妄加讨伐，若有骄逆不行此道者，故用诛伐，故云「利用侵伐，无不利」。张氏云「葛伯仇饷，汤往伐之」是也。</p><p>上六：鸣谦，利用行师，征邑国者，不预内政，于谦不实，惟有虚声外扬而已，故曰「鸣谦」也。有所兴为，其功未得，但可征旁邑国骄逆之人，故曰「利用行师征邑国」也。</p>',23)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
